async function hashPassword(value) { const bytes = new Uint8Array([...value].map(char => char.charCodeAt(0))); const digest = await crypto.subtle.digest('SHA-256', bytes); return [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join(''); }
function passwordRules(password, confirmation) { return { length: password.length >= 8, letters: /[A-Za-z]/.test(password), numbers: /\d/.test(password), match: password.length > 0 && password === confirmation }; }
function icon(name, size = 16) { return `<i data-lucide="${name}" width="${size}" height="${size}"></i>`; }
function startLuxuryCanvas() { const canvas = document.querySelector('#luxury-canvas'); const context = canvas.getContext('2d'); let width = 0; let height = 0; let dpr = 1; let nodes = []; const silver = ['#C0C0C0', '#E8E8E8', '#F5F5F5', '#A8A8A8']; const count = () => window.innerWidth < 560 ? 52 : window.innerWidth < 1000 ? 84 : 124; const resize = () => { dpr = Math.min(window.devicePixelRatio || 1, 2); width = window.innerWidth; height = window.innerHeight; canvas.width = width * dpr; canvas.height = height * dpr; canvas.style.width = `${width}px`; canvas.style.height = `${height}px`; context.setTransform(dpr, 0, 0, dpr, 0, 0); const target = count(); if (nodes.length < target) for (let index = nodes.length; index < target; index += 1) nodes.push({ x: Math.random() * width, y: Math.random() * height, vx: (Math.random() - .5) * .12, vy: (Math.random() - .5) * .12, radius: 1 + Math.random() * 1.7, alpha: .22 + Math.random() * .56, phase: Math.random() * Math.PI * 2, color: silver[index % silver.length], highlight: Math.random() > .88 }); if (nodes.length > target) nodes.length = target; }; const draw = time => { context.clearRect(0, 0, width, height); nodes.forEach(node => { node.x += node.vx; node.y += node.vy; if (node.x < -20 || node.x > width + 20) node.vx *= -1; if (node.y < -20 || node.y > height + 20) node.vy *= -1; }); for (let first = 0; first < nodes.length; first += 1) { const node = nodes[first]; for (let second = first + 1; second < nodes.length; second += 1) { const other = nodes[second]; const dx = node.x - other.x; const dy = node.y - other.y; const distance = Math.sqrt(dx * dx + dy * dy); if (distance < 128) { const opacity = (1 - distance / 128) * .22; context.beginPath(); context.moveTo(node.x, node.y); context.lineTo(other.x, other.y); context.strokeStyle = `rgba(192,192,192,${opacity})`; context.lineWidth = .55; context.stroke(); } } } nodes.forEach(node => { const pulse = node.highlight ? (Math.sin(time * .001 + node.phase) + 1) * .5 : 0; const glow = node.highlight ? 9 + pulse * 8 : 4; context.beginPath(); context.shadowBlur = glow; context.shadowColor = node.color; context.fillStyle = node.color; context.globalAlpha = Math.min(1, node.alpha + pulse * .16); context.arc(node.x, node.y, node.radius + pulse * .6, 0, Math.PI * 2); context.fill(); context.shadowBlur = 0; }); context.globalAlpha = 1; requestAnimationFrame(draw); }; resize(); window.addEventListener('resize', resize); requestAnimationFrame(draw); }
function initials(name) { return name.split(' ').map(s => s[0]).slice(0,2).join('').toUpperCase(); }
function todayKey(date = new Date()) { const operationalDate = new Date(date); if (operationalDate.getHours() === 0 && operationalDate.getMinutes() === 0) operationalDate.setDate(operationalDate.getDate() - 1); const year = operationalDate.getFullYear(); const month = String(operationalDate.getMonth() + 1).padStart(2, '0'); const day = String(operationalDate.getDate()).padStart(2, '0'); return `${year}-${month}-${day}`; }
function todayPermissionHistory() { const today = todayKey(); return state.permissionHistory.filter(permission => { const timestamp = permission.createdAt || permission.startTime || permission.completedAt; return timestamp && todayKey(new Date(timestamp)) === today; }); }
function currentUserRole() { return state.user?.role || ''; }
function can(page) { return permissions[currentUserRole()]?.includes(page); }
function saveLog(activity, detail) { state.logs.unshift({ id: Date.now(), nama: state.user.nama, role: state.user.role, aktivitas: activity, detail, created_at: new Date().toLocaleString('id-ID') }); state.logs = state.logs.slice(0,100); persist(); }
function toast(message, type = 'success') { const el = document.createElement('div'); el.className = 'toast'; el.innerHTML = `${icon(type === 'success' ? 'check-circle-2' : 'alert-triangle')}<span>${message}</span>`; document.querySelector('#toast-region').append(el); setTimeout(() => el.remove(), 3000); }
function formatTime(ms) { const total = Math.max(0, Math.floor(ms / 1000)); return `${String(Math.floor(total / 60)).padStart(2,'0')}:${String(total % 60).padStart(2,'0')}`; }
