  if (state.page === 'staffAttendance') { const priority = document.querySelector('.priority-inline'); const divisions = document.querySelector('.division-sections'); if (priority && divisions) divisions.before(priority); }
  document.querySelectorAll('[data-page]').forEach(btn => btn.onclick = () => { state.page = btn.dataset.page; document.querySelector('#sidebar').classList.remove('open'); render(); });
