  document.querySelector('#notification-btn').onclick = () => { const active = state.activePermissions.length; toast(active ? `${active} anggota sedang izin. Kapasitas diperbarui realtime.` : 'Tidak ada notifikasi baru. Semua kapasitas tersedia.'); };
